-- 29 September 2026 daily current-affairs desk.
-- Every brief was checked against the linked primary official source.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-29-india-uae-investment-task-force$$, $$2026-09-29$$,
  $$India and UAE review CEPA implementation and joint-investment projects$$,
  $$At the 14th India-UAE High Level Joint Task Force on Investments in Mumbai, the two countries reviewed CEPA subcommittees, investment projects and financial-sector work on local-currency settlement, payment-system integration and central-bank digital currencies.$$,
  $$This connects bilateral economic diplomacy with CEPA, bilateral investment arrangements and cross-border payment cooperation. The Task Force is an investment-facilitation mechanism, not a new trade agreement.$$,
  $$The High Level Joint Task Force on Investments was established in 2013 to promote trade, investment and resolution of investor issues between India and the UAE. CEPA is the Comprehensive Economic Partnership Agreement; it is one part of the wider economic relationship.$$,
  $$14th India-UAE High Level Joint Task Force Meeting Held in Mumbai$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315968&reg=3&lang=1$$,
  $$Ministry of Commerce and Industry / Press Information Bureau$$, $$2026-09-28$$,
  $$["The India-UAE High Level Joint Task Force on Investments was established in 2013.","The 14th meeting was held in Mumbai.","The meeting reviewed CEPA progress and joint investment projects.","The two sides reviewed work on local-currency settlement, payment systems and central-bank digital currencies."]$$::jsonb,
  $$[{"question":"What does CEPA stand for?","answer":"Comprehensive Economic Partnership Agreement."},{"question":"What is the basic role of the India-UAE High Level Joint Task Force?","answer":"To facilitate investment and address related issues between the two countries."}]$$::jsonb,
  $${"title":"Economic cooperation through an investment task force","steps":["A bilateral forum identifies investment and trade priorities.","Officials review agreements such as CEPA and project progress.","Financial and payment cooperation can reduce transaction frictions.","Follow-up mechanisms address investor and implementation issues."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-telecom-subscription-data-august$$, $$2026-09-29$$,
  $$TRAI releases August 2026 telecom subscription indicators$$,
  $$TRAI reported 1,360.70 million total telephone subscribers and 1,101.21 million broadband subscribers at the end of August 2026. The total telephone base rose by 6.42 million during the month, while broadband subscriptions rose by 0.61%. $$,
  $$This is official infrastructure data for questions on teledensity, broadband and the regulator’s role. It is a monthly statistical release, so distinguish subscriber connections from people and broadband from telephone subscriptions.$$,
  $$The Telecom Regulatory Authority of India regulates telecommunications. Teledensity expresses telephone connections per 100 people, while mobile-number portability allows a subscriber to retain a mobile number while changing the service provider.$$,
  $$Highlights of Telecom Subscription Data at the end of August 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2316034&reg=3&lang=1$$,
  $$Telecom Regulatory Authority of India / Press Information Bureau$$, $$2026-09-28$$,
  $$["Total telephone subscribers stood at 1,360.70 million at end-August 2026.","Total broadband subscribers stood at 1,101.21 million.","The total telephone base added 6.42 million subscribers in August.","TRAI reported 15.83 million requests for mobile-number portability during the month."]$$::jsonb,
  $$[{"question":"What does teledensity measure?","answer":"Telephone connections per 100 people."},{"question":"Which statutory regulator releases India telecom subscription data?","answer":"The Telecom Regulatory Authority of India (TRAI)."}]$$::jsonb,
  $${"title":"How a telecom indicator is built","steps":["Service providers submit subscriber data to the regulator.","TRAI aggregates wireless and wireline connections.","Broadband and telephone bases are reported separately.","Teledensity relates the connection base to population estimates."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-livestock-insurance-portal$$, $$2026-09-29$$,
  $$Livestock Insurance Portal launched under the National Livestock Mission$$,
  $$The Department of Animal Husbandry and Dairying launched the Livestock Insurance Portal for the Livestock Insurance activity of the National Livestock Mission. It brings policy issuance, premium management, claims, beneficiary verification and monitoring onto one digital interface.$$,
  $$This is a rural-livelihood and digital-governance update. For exams, connect livestock risk protection to the National Livestock Mission and know that the portal is a delivery platform rather than an insurance company.$$,
  $$Livestock can be a major income source for rural households, but mortality, disease, accidents and disasters create financial risk. A digital insurance workflow can link farmers, States, insurers and implementing agencies while making claim tracking more transparent.$$,
  $$Livestock Insurance Portal launched under the National Livestock Mission$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2316242&reg=3&lang=1$$,
  $$Department of Animal Husbandry and Dairying / Press Information Bureau$$, $$2026-09-28$$,
  $$["The portal supports the Livestock Insurance activity of the National Livestock Mission.","It covers policy issuance, premium management, claims, beneficiary verification and monitoring.","It connects farmers, State governments, insurers and implementing agencies.","The release stated that more than 30 lakh animals had been insured during the year."]$$::jsonb,
  $$[{"question":"Which mission contains the cited livestock-insurance activity?","answer":"The National Livestock Mission (NLM)."},{"question":"Name one portal function beyond enrolment.","answer":"Claim processing, beneficiary verification, premium management or real-time monitoring."}]$$::jsonb,
  $${"title":"Digital livestock-insurance delivery","steps":["A farmer seeks cover for an eligible animal.","The platform records policy and premium information.","Verification and monitoring support implementation.","A claim can move through a trackable digital workflow."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-steel-industry-safety-council$$, $$2026-09-29$$,
  $$Ministry of Steel to establish the Steel Industry Safety Council$$,
  $$The Ministry of Steel decided to set up the Steel Industry Safety Council as an apex body and a supporting Steel Industry Safety Directorate. The Council will assess safety, approve recommended practices and review serious accidents and near misses; the Directorate will support audits, investigations and standards work.$$,
  $$This is an industrial-safety institutional development. It tests the distinction between a policy-level council and its technical support directorate, as well as coordination with bodies such as DGMS, PESO and NDMA.$$,
  $$Steelmaking involves high-temperature, mechanical, electrical, chemical and occupational hazards. Near-miss reporting is preventive: it examines an unsafe event that did not cause injury or damage but could have done so.$$,
  $$Ministry of Steel Announces Apex Body for Strengthening Safety Standards and Safety Culture$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2316115&reg=3&lang=1$$,
  $$Ministry of Steel / Press Information Bureau$$, $$2026-09-28$$,
  $$["The Steel Industry Safety Council (SISC) will function under the Ministry of Steel.","The Secretary, Ministry of Steel, will chair the SISC.","DGMS, PESO and NDMA are among the organisations represented in the Council.","The Steel Industry Safety Directorate will support audits, investigations, training and safety standards."]$$::jsonb,
  $$[{"question":"What is the role of the Steel Industry Safety Directorate?","answer":"It provides technical support, including audits, investigations, information and standards work."},{"question":"Why are near misses reviewed in industrial safety?","answer":"They reveal risks before they result in a serious accident."}]$$::jsonb,
  $${"title":"Two-layer industrial-safety framework","steps":["The apex council sets direction and reviews sector safety.","Technical specialists support evidence, audits and investigations.","Standards and recommended practices guide plant-level prevention.","Training and incident learning improve safety culture over time."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-fastag-annual-pass-milestone$$, $$2026-09-29$$,
  $$FASTag Annual Pass crosses one-crore issuance milestone$$,
  $$The Ministry of Road Transport and Highways said one crore FASTag Annual Passes had been issued since the product’s launch on 15 August 2025. The pass is for eligible non-commercial vehicles and is usable at about 1,150 National Highway and National Expressway fee plazas.$$,
  $$This is a transport-digitalisation milestone. It is useful for remembering the Annual Pass terms without confusing the pass with FASTag itself, which is the electronic toll-collection tag linked to a vehicle.$$,
  $$The Annual Pass is activated through the Rajmargyatra app on an existing valid FASTag. The official release specifies a one-time payment of ₹3,075 for one year or 200 toll-plaza crossings, subject to the stated conditions.$$,
  $$FASTag Annual Pass Reaches One Crore Milestone$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2316062&reg=3&lang=1$$,
  $$Ministry of Road Transport and Highways / Press Information Bureau$$, $$2026-09-28$$,
  $$["One crore FASTag Annual Passes had been issued since the 15 August 2025 launch.","The Annual Pass is for non-commercial vehicles with a valid FASTag.","It applies at about 1,150 National Highway and National Expressway fee plazas.","The pass is activated through the Rajmargyatra app after the stated one-time payment."]$$::jsonb,
  $$[{"question":"Which app is named for activation of the FASTag Annual Pass?","answer":"Rajmargyatra."},{"question":"Is the Annual Pass intended for commercial vehicles?","answer":"No; the release specifies eligible non-commercial vehicles."}]$$::jsonb,
  $${"title":"Annual-pass tolling flow","steps":["A vehicle has a valid FASTag.","The eligible owner makes the stated one-time payment.","The Rajmargyatra app activates the Annual Pass on the existing tag.","The pass works within its validity or crossing limit at covered plazas."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-india-cofo-28-forest-restoration$$, $$2026-09-29$$,
  $$India presents forest-restoration progress at FAO Committee on Forestry$$,
  $$At the 28th session of the FAO Committee on Forestry in Rome, India reported progress under its Bonn Challenge pledge and highlighted the Aravalli Green Wall and MISHTI. It stated that 21.76 million hectares had been brought under restoration against a 26-million-hectare Bonn Challenge pledge for 2030.$$,
  $$This is environment and international-organisation material. Learn the difference between a restoration pledge, forest-cover statistics and programmes such as MISHTI; none alone means that every plantation is a forest restoration project.$$,
  $$COFO is the Food and Agriculture Organization’s Committee on Forestry. The Bonn Challenge is a global restoration effort. MISHTI focuses on mangrove plantation and restoration, while the Aravalli Green Wall addresses degraded landscapes in the Aravalli range.$$,
  $$India showcases Forest and Landscape Restoration Initiatives at COFO 28$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2316216&reg=3&lang=1$$,
  $$Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-09-28$$,
  $$["COFO is the Food and Agriculture Organization Committee on Forestry.","India stated a Bonn Challenge pledge to restore 26 million hectares by 2030.","The release reported 21.76 million hectares brought under restoration.","MISHTI advances mangrove restoration and the Aravalli Green Wall targets degraded land in that landscape."]$$::jsonb,
  $$[{"question":"Which UN specialised agency hosts the Committee on Forestry?","answer":"The Food and Agriculture Organization (FAO)."},{"question":"What ecosystem does MISHTI focus on?","answer":"Mangrove ecosystems."}]$$::jsonb,
  $${"title":"From a restoration pledge to landscape work","steps":["A country makes a restoration commitment.","Degraded areas are identified and prioritised.","Programmes restore forests, mangroves or other landscapes.","Progress is reported through national and international forums."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-iwc-70-cetacean-conservation$$, $$2026-09-29$$,
  $$India highlights cetacean conservation at IWC-70 in Hobart$$,
  $$India participated in the 70th International Whaling Commission meeting in Hobart and highlighted science-based conservation of whales and other cetaceans. The release links this work to India’s membership of the IWC, Project Dolphin and legal protection for cetaceans in Indian waters.$$,
  $$This is a biodiversity and international-conventions brief. It tests the IWC’s treaty basis and the taxonomic group “cetaceans”, while connecting marine conservation with India’s domestic legal and programme framework.$$,
  $$The International Whaling Commission was established under the International Convention for the Regulation of Whaling, signed in 1946. Cetaceans are marine mammals that include whales, dolphins and porpoises. India joined the IWC in 1981.$$,
  $$India Reaffirms Commitment to Conservation of Whales and Other Cetaceans at IWC-70$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2316042&reg=3&lang=1$$,
  $$Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-09-28$$,
  $$["IWC-70 was held in Hobart, Australia.","The IWC derives from the International Convention for the Regulation of Whaling, signed in 1946.","India has been an IWC member since 1981.","Cetaceans include whales, dolphins and porpoises; Project Dolphin uses a broader aquatic-ecosystem approach."]$$::jsonb,
  $$[{"question":"What treaty established the International Whaling Commission?","answer":"The International Convention for the Regulation of Whaling."},{"question":"Which animals belong to the cetacean group?","answer":"Whales, dolphins and porpoises."}]$$::jsonb,
  $${"title":"International and domestic cetacean conservation","steps":["The IWC provides a treaty-based international forum.","Science informs assessment of populations and threats.","Countries protect habitats and species through domestic law and programmes.","International cooperation supports conservation across marine ranges."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-29-iip-august-2026$$, $$2026-09-29$$,
  $$August IIP grows 8.0% on the 2022-23 base$$,
  $$The Ministry of Statistics and Programme Implementation released the quick estimate of the Index of Industrial Production for August 2026: overall output grew 8.0% year on year. Manufacturing grew 9.0%, electricity and gas supply 12.3%, while mining and quarrying contracted 5.6%. $$,
  $$IIP is a core macroeconomic indicator. Students should know its base year, that quick estimates can be revised, and that sectoral growth rates may move differently from the overall index.$$,
  $$IIP tracks changes in the volume of industrial production. The current series uses base 2022-23=100. MoSPI releases a quick estimate around the 28th of each month using data reported by source agencies; later data can revise the figure.$$,
  $$Quick Estimates of Index of Industrial Production and Use-Based Index for August 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315957&reg=3&lang=1$$,
  $$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-09-28$$,
  $$["The IIP series uses base year 2022-23=100.","Overall IIP grew 8.0% year on year in August 2026.","Manufacturing grew 9.0% and electricity plus gas supply grew 12.3%.","Mining and quarrying contracted 5.6%; August figures are quick estimates subject to revision."]$$::jsonb,
  $$[{"question":"What is the base year of the IIP series cited in this release?","answer":"2022-23."},{"question":"Are IIP quick estimates final when first released?","answer":"No; they may be revised as updated source data are received."}]$$::jsonb,
  $${"title":"Reading an IIP release","steps":["Source agencies collect production data from establishments.","MoSPI compiles a quick estimate using the IIP base year.","Sector and use-based movements explain the headline change.","Updated data lead to later revisions."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
  $$2026-09-29-india-uae-investment-task-force$$,
  $$2026-09-29-telecom-subscription-data-august$$,
  $$2026-09-29-livestock-insurance-portal$$,
  $$2026-09-29-steel-industry-safety-council$$,
  $$2026-09-29-fastag-annual-pass-milestone$$,
  $$2026-09-29-india-cofo-28-forest-restoration$$,
  $$2026-09-29-iwc-70-cetacean-conservation$$,
  $$2026-09-29-iip-august-2026$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
